import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Chương 106｜Tinh chỉnh Cảnh giới · Cảnh Cảm Nguyên｜So sánh chi tiết: phái Cướp vs phái Cộng sinh","description":"","frontmatter":{"title":"Chương 106｜Tinh chỉnh Cảnh giới · Cảnh Cảm Nguyên｜So sánh chi tiết: phái Cướp vs phái Cộng sinh","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","体系对比"],"related":["04-反掠夺主义核心论纲","01-锚点共生文明宣言","14-修炼境界统一划分"]},"headers":[],"relativePath":"vi/106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"vi/106_模块1-感元境-掠夺派vs共生派对比.md"}'),g={name:"vi/106_模块1-感元境-掠夺派vs共生派对比.md"};function a(u,n,o,l,p,m){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="chuong-106-canh-cam-nguyen-so-sanh-chi-tiet-phai-cuop-va-phai-cong-sinh" tabindex="-1">Chương 106｜Cảnh Cảm Nguyên: So sánh chi tiết phái Cướp và phái Cộng sinh <a class="header-anchor" href="#chuong-106-canh-cam-nguyen-so-sanh-chi-tiet-phai-cuop-va-phai-cong-sinh" aria-label="Permalink to &quot;Chương 106｜Cảnh Cảm Nguyên: So sánh chi tiết phái Cướp và phái Cộng sinh&quot;">​</a></h1><blockquote><p>Thuộc mô đun: Mô đun Một · Tinh chỉnh sâu Cảnh giới | Đối chiếu nền tảng: Tài liệu 04, 01, 14</p></blockquote><h2 id="dan-nhap-cung-mot-điem-xuat-phat-hai-con-đuong-nguoc-nhau" tabindex="-1">Dẫn nhập: Cùng một điểm xuất phát, hai con đường ngược nhau <a class="header-anchor" href="#dan-nhap-cung-mot-điem-xuat-phat-hai-con-đuong-nguoc-nhau" aria-label="Permalink to &quot;Dẫn nhập: Cùng một điểm xuất phát, hai con đường ngược nhau&quot;">​</a></h2><p>Cảnh Cảm Nguyên là điểm xuất phát của chín cảnh giới và cũng là ngã tư đầu tiên Muôn tộc lựa chọn lộ trình. Cùng thiên phú, cùng vũ trụ, thậm chí cùng cụm từ &quot;cảm thọ năng lượng&quot;, nhưng phái Cướp và phái Cộng sinh cho hai câu trả lời hoàn toàn trái ngược. Bài này lấy Cảnh Cảm Nguyên làm lát cắt, so sánh hệ thống khác biệt bản chất của hai lộ trình trên đường đi, cái giá và kết cục, đồng thời trả lời câu hỏi cốt lõi: vì sao trần của phái Cướp luôn sàn của phái Cộng sinh?</p><p>Sáu Công lý Tối thượng là ranh giới chia hai lộ trình: Công lý Chủ nghĩa Chống cướp — nguồn của ngụm năng lượng đầu tiên quyết định lộ trình; Công lý Cộng hòa Muôn tộc — trong mắt phái Cộng sinh Muôn tộc là đồng tu, trong mắt phái Cướp tất cả chúng sinh là mồi; Công lý Thăng chiều Tập thể — phái Cộng sinh mạnh để cùng lên, phái Cướp mạnh để độc chiếm, chống đại tài tiểu dụng; Công lý Tự luật Nhân quả — mọi thao tác phái Cộng sinh có thể ghi, có thể truy và có thể sửa; Công lý Ưu tiên Pháp tắc — khung pháp luật so sánh phái Cướp vs phái Cộng sinh ổn định tự nhất quán, không vì tiện lợi cốt truyện mà ăn sách cải thiết, có thể mở rộng vô hạn mà không sụp đổ. Luật Bình đẳng Vô hạn Toàn thể Chúng sinh xác lập ai cũng tự mang Sức mạnh Vô hạn Cơ bản; người tu lười biếng giữ vô hạn cơ bản bảo toàn sẽ không bị thời đại đào thải, kẻ cuồng việc và Thiếu niên Tôn giả có thể chồng thêm các cấp vô hạn cao hơn; bản nguyên vô hạn ai cũng tự mang, cướp đoạt đương nhiên mất ý nghĩa.</p><h2 id="i-bang-so-sanh-he-thong" tabindex="-1">I. Bảng so sánh hệ thống <a class="header-anchor" href="#i-bang-so-sanh-he-thong" aria-label="Permalink to &quot;I. Bảng so sánh hệ thống&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phía</th><th>phái Cướp · Cảnh Cảm Nguyên</th><th>phái Cộng sinh · Cảnh Cảm Nguyên</th></tr></thead><tbody><tr><td>Nguồn năng lượng</td><td>Nuốt năng lượng người khác, cướp cơ hội cảm tri của người</td><td>Hấp thụ năng lượng tự do vũ trụ theo quy phạm, tuần hoàn hai chiều bản nguyên Muôn tộc</td></tr><tr><td>Phương thức cảm tri</td><td>Đánh cắp thành quả cảm tri của người, nhanh nhưng thô</td><td>Kinh nghiệm tự giác tỉnh thức cảm tri, nền tảng tinh khiết</td></tr><tr><td>Cái giá đột phá</td><td>Tiêu hao thiên phú, bản nguyên bất thuần, nguy hiểm khuếch đại dọc đường</td><td>Cái giá thực + giám sát Neo, có thể sửa và có thể làm lại</td></tr><tr><td>Môi trường giám sát</td><td>Luật rừng, không giám sát, không trách nhiệm</td><td>mạng lưới Như Lai Tạng + giám sát đa tầng bảo vệ toàn trình</td></tr><tr><td>Vị trí xã hội</td><td>Con mồi hay thợ săn, một trong hai</td><td>Đồng sáng tạo, Ai cũng có con đường</td></tr><tr><td>Kết cục</td><td>Trần hiệu suất: một bước không đi nổi, không chạm Cảnh Nguyên bản</td><td>Cảnh Nguyên bản và trên, trọng lượng văn minh tăng cùng đóng góp</td></tr></tbody></table><h2 id="ii-ba-sai-lam-cua-phai-cuop-đa-chieu-tai-canh-cam-nguyen" tabindex="-1">II. Ba sai lầm của phái Cướp đã chiếu tại Cảnh Cảm Nguyên <a class="header-anchor" href="#ii-ba-sai-lam-cua-phai-cuop-đa-chieu-tai-canh-cam-nguyen" aria-label="Permalink to &quot;II. Ba sai lầm của phái Cướp đã chiếu tại Cảnh Cảm Nguyên&quot;">​</a></h2><p>Ba sai lầm của chủ nghĩa cướp đoạt trong Tài liệu 04 (Luận cương Cốt lõi Chủ nghĩa Chống cướp) đã toàn bộ chiếu ra tại Cảnh Cảm Nguyên:</p><ol><li>Sai lầm vũ trụ luận: coi vũ trụ là bãi săn hữu hạn — ngay tại Cảnh Cảm Nguyên đã học &quot;cướp&quot;, từ ngày đầu đã thừa nhận tiến hóa là trò chơi tổng không</li><li>Sai lầm đạo đức: đặt quyền tiến hóa kẻ mạnh trên quyền tồn tại kẻ yếu — một khi &quot;nuốt&quot; mở tại Cảnh Cảm Nguyên, không đường lui</li><li>Sai lầm hiệu suất: tin cướp đoạt là nhanh nhất — cảm tri trộm được tại Cảnh Cảm Nguyên mang tàn ý chí của chủ nhân gốc; cái giá tinh luyện về sau vượt xa tự tu</li></ol><p>Tu sĩ phái Cướp tại Cảnh Cảm Nguyên, tốc độ nhanh nhất hao tổn nền tảng đắt nhất; tu sĩ phái Cộng sinh tại Cảnh Cảm Nguyên, tiết tấu ổn định nhất tích lũy vốn dày nhất.</p><h2 id="iii-ke-cuop-van-minh-thien-tam-khong-cuu-đuoc-lo-trinh-cuop" tabindex="-1">III. Kẻ cướp văn minh: thiện tâm không cứu được lộ trình cướp <a class="header-anchor" href="#iii-ke-cuop-van-minh-thien-tam-khong-cuu-đuoc-lo-trinh-cuop" aria-label="Permalink to &quot;III. Kẻ cướp văn minh: thiện tâm không cứu được lộ trình cướp&quot;">​</a></h2><p>Phải đối mặt một đối tượng phức tạp: &quot;kẻ cướp văn minh&quot; — tương đối thiện lương, thậm chí thành tâm bảo hộ muôn sinh. Đặc điểm: không chủ động làm ác, sẵn sàng che chở, thành tâm với người trong nhà, nhưng toàn bộ hệ thống vẫn đặt trên nền cướp đoạt — độc chiếm đại đạo thượng vị, độc hưởng patent bản nguyên, dưới danh nghĩa &quot;bảo hộ&quot; thực hành &quot;ban ơn&quot;.</p><p>Tại Cảnh Cảm Nguyên, giáo dục kiểu &quot;kẻ cướp văn minh&quot; là: dùng tài nguyên tốt nhất nuôi thiên tài, nhưng không bao giờ thật sự nhường đường — bởi &quot;con đường&quot; tự nó là hàng độc quyền. Đây là lý do kẻ mạnh thiện chí vẫn không đạt độ cao văn minh siêu đa nguyên: hắn đứng trên đỉnh hệ thống cướp, trần của hệ thống cướp chính là trần của hắn.</p><h2 id="iv-vi-sao-phai-cuop-chac-chan-thoai-bo-lich-su" tabindex="-1">IV. Vì sao phái Cướp chắc chắn thoái bộ lịch sử <a class="header-anchor" href="#iv-vi-sao-phai-cuop-chac-chan-thoai-bo-lich-su" aria-label="Permalink to &quot;IV. Vì sao phái Cướp chắc chắn thoái bộ lịch sử&quot;">​</a></h2><p>Đích cấu trúc của văn minh phái Cướp là: kẻ mạnh đổ, văn minh thoái. Toàn bộ vận hành hệ thống phụ thuộc thiện chí và sức mạnh của cá nhân đỉnh điểm — hắn còn sống, trật tự miễn cưỡng duy trì; hắn rời đi, bãi săn khởi động lại. &quot;Phụ thuộc đơn điểm&quot; này không phải khiếm khuyết đạo đức, mà là cấu trúc: hệ thống cướp chưa bao giờ viết trật tự vào thể chế, chỉ đem trật tự đặt cược vào cá nhân mạnh.</p><p>Đây chính là hình thái nguyên thủy của &quot;tính duy nhất nhân vật chính&quot;: sự sống còn của văn minh phụ thuộc một người. Câu trả lời của Văn minh Cộng sinh Neo là viết hòa bình vào thể chế và Netz der Gesetze (Neo, tòa án, nghị viện, hợp đồng sản xuất) — dù Cường giả Tối cao Vị diện mạnh nhất có đổ, mạng cộng sinh vẫn vận hành.</p><h2 id="v-ke-bat-nghia-đung-đao-nguong-thang-canh-va-lo-trinh-moi" tabindex="-1">V. Kẻ bất nghĩa đúng đạo: ngưỡng thăng cảnh và lộ trình mới <a class="header-anchor" href="#v-ke-bat-nghia-đung-đao-nguong-thang-canh-va-lo-trinh-moi" aria-label="Permalink to &quot;V. Kẻ bất nghĩa đúng đạo: ngưỡng thăng cảnh và lộ trình mới&quot;">​</a></h2><p>Để nhảy từ phái Cướp sang phái Cộng sinh, phải qua ngưỡng thăng cảnh gọi là &quot;kẻ bất nghĩa đúng đạo&quot;: dám xé bỏ quyền lợi cũ được thần thánh hóa, dám lật đổ logic nền của hệ cũ, không sợ áp lực của nhóm lợi ích cũ, và viết lại khế ước công bằng cộng sinh.</p><p>Nhân vật chính Lín Hào chính là đại biểu lộ trình này: xuất thân bản nguyên bậc thấp, đi đường thú hồn chỉ hại thân, hắn là nạn nhân quy tắc cũ chứ không phải người thụ hưởng — buộc phải dựng lại quy tắc, suy diễn ra Đường D · Linh Hoàn Pháp Luật Nhân tạo của Rén Zú, thay săn bắt và thu hoạch linh hoàn bằng luật nhân tạo, từ nạn nhân của hệ thống cướp đoạt thành người tái tạo văn minh cộng sinh. Cảnh Cảm Nguyên là cửa sớm nhất của ngưỡng này: người ngay từ điểm xuất phát đã chọn lộ trình cộng sinh, đã gần với văn minh siêu đa nguyên hơn &quot;kẻ cướp văn minh&quot; bị kẹt trên đỉnh hệ thống cướp đoạt.</p><h2 id="vi-nam-điem-cot-loi" tabindex="-1">VI. Năm Điểm cốt lõi <a class="header-anchor" href="#vi-nam-điem-cot-loi" aria-label="Permalink to &quot;VI. Năm Điểm cốt lõi&quot;">​</a></h2><ul><li>Chống lãng phí năng lượng: phái Cướp lãng phí thiên phú vào đấu tự hủy nội bộ, phái Cộng sinh đầu tư thiên phú vào xây dựng tiến độ</li><li>Chống cướp đoạt: phân kỳ bản chất hai lộ trình nằm ở ngụm năng lượng đầu tiên tại Cảnh Cảm Nguyên</li><li>Đối chiếu trần Táng La: &quot;phổ dân&quot; kiểu Táng La vẫn là hệ thống ban ơn — muôn sinh đều phụ thuộc kẻ mạnh, không phải đồng kiến; phái Cộng sinh có Ai cũng có con đường, không ai phụ thuộc ai</li><li>Phủ toàn Muôn tộc: mắt phái Cướp muôn sinh là mồi và công cụ, mắt phái Cộng sinh Muôn tộc là đồng tu — phủ 99% không có ngoại lệ</li><li>Siêu đa nguyên toàn mở: phái Cướp độc chiếm tất cả, phái Cộng sinh từ Cảnh Cảm Nguyên đã mở toàn bộ cảnh giới</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>So sánh phái Cướp và phái Cộng sinh tại Cảnh Cảm Nguyên cô đọng xung đột cốt lõi của toàn lịch sử vũ trụ: cướp đoạt sinh ra kẻ mạnh chớp nhoáng và thoái bộ vĩnh viễn, cộng sinh sinh ra thịnh vượng bền lâu và thăng cảnh tập thể. Tu sĩ phái Cướp tại Cảnh Cảm Nguyên dốc sức giành vạch xuất phát, cuối cùng mới biết vạch đích gác sàn nhà chính mình; tu sĩ phái Cộng sinh tại Cảnh Cảm Nguyên bước đầu vững vàng, cuối cùng phát hiện đoạn đường kết thúc là Cảnh Naga siêu đa nguyên. Lựa chọn đã định từ điểm xuất phát — đây không phải số phận, đây là công lý.</p><h2 id="lien-quan" tabindex="-1">Liên quan <a class="header-anchor" href="#lien-quan" aria-label="Permalink to &quot;Liên quan&quot;">​</a></h2><ul><li>Tài liệu liên quan: <a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> · <a href="./01-锚点共生文明宣言.html">01-锚点共生文明宣言</a> · <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a></li><li>Website chính thức: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',26)])])}const e=h(g,[["render",a]]);export{s as __pageData,e as default};
